"""This file contains the Monaco Adaptive Script Dialogs Page Object class for the Adaptive Script Dialogs used with Monaco.
This class serves as an interface to the Monaco Scripting dialog popups. It provides a mechanism to wait for the
AdaptivePlanningWorkflow.exe process to start by retrying the AUT attach until it succeeds. An object should be created from
this class and used for all interactions with the Adaptive Script dialogs.
"""

import logging
from .. interactions import MonacoScriptingDialogsFuncs
import interops.libraries.desktop.aut_manager as AutManager
from interops.libraries.monaco import MonacoAutController
from interops.libraries.squish_actions.constants import MONACO_SCRIPTING_APP_NAME

logger = logging.getLogger(__name__)

class AdaptiveScriptingDialogs():
    def __init__(self, hostAddress: str, autAttachRetries: int = 2):
        '''
        Attaches to the AdaptivePlanningWorkflow AUT for a given number of attempts to create the Monaco script
        dialog driver (handle to the Squish application context). The number of attach retries can be increased
        to wait for the AdaptivePlanningWorkflow.exe to start.

        Args:
            hostAddress (str): The host address of the Monaco AdaptivePlanningWorkflow AUT
            autAttachRetries (int): The number of times to attempt attaching to the AdaptivePlanningWorkflow AUT
        '''
        self.monaco_script_dialog_host_address = hostAddress
        self.monaco_script_dialog_driver = None
        # Check if squish has already attached to AdaptivePlanningWorkflow AUT process, if not try
        # attaching to it repeatedly until the maximum number of retries is reached.
        if not self.__attach_to_adaptive_planning_workflow_aut(autAttachRetries):
            raise RuntimeError('Failed to attach to AdaptivePlanningWorkflow AUT!')


    def __attach_to_adaptive_planning_workflow_aut(self, attachRetries: int = 2) -> bool:
        '''
        Attempts to attach repeatedly to the AdaptivePlanningWorkflow window/AUT directly for the no. of retries specified.
        This also serves as a waiting mechanism to wait for the AdaptivePlanningWorkflow.exe to start.
        Squish recognises the Monaco scripting dialogs as a separate AUT and as it is not part of the main Monaco AUT.

        Args:
            attachRetries (int): The number of times to attempt attaching to the AdaptivePlanningWorkflow AUT
        '''
        if not AutManager.is_aut_running(MONACO_SCRIPTING_APP_NAME):
            adaptive_script_dialog_driver = MonacoAutController.monaco_script_aut(serverAddress=self.monaco_script_dialog_host_address, serverPort=4322)
            for i in range(attachRetries):
                try:
                    print(f"Monaco Adaptive Scripting dialog attach attempt no. {i+1}")
                    self.monaco_script_dialog_driver = adaptive_script_dialog_driver.attach_to_aut(kill_existing_process=False, get_running_aut_pid_retries=50)
                    return True
                except Exception as e:
                    logger.info(f"Failed to attach to Monaco Adaptive Scripting dialog on attempt no: {i+1}. Error: {e}.")
        return False

    def setup_adapt_ready(self, waitTimeout=20000) -> bool:
        '''
        Waits for the set up adapt dialog to be ready.

        Args:
            waitTimeout (int): The time in milliseconds to wait for the dialog to appear

        Returns:
            bool - True if set up adapt dialog is ready, False otherwise
        '''
        try:
            if not self.monaco_script_dialog_driver:
                self.__attach_to_adaptive_planning_workflow_aut()
            return MonacoScriptingDialogsFuncs.wait_for_setup_adapt_dialog(waitTimeout)
        except Exception as e:
            logger.info(f"set up adapt dialog failed to open or was not recognised. Error: {e}.")
            return False

    def action_required_ready(self, waitTimeout=5000) -> bool:
        '''
        Waits for the action required dialog to be ready.

        Args:
            waitTimeout (int): The time in milliseconds to wait for the dialog to appear

        Returns:
            bool - True if action required dialog is ready, False otherwise
        '''
        try:
            if not self.monaco_script_dialog_driver:
                self.__attach_to_adaptive_planning_workflow_aut()
            return MonacoScriptingDialogsFuncs.wait_for_action_requied_dialog(waitTimeout)
        except Exception as e:
            logger.info(f"Action Required dialog failed to open or was not recognised. Error: {e}.")
            return False

    def wait_for_set_couch_and_review_contours_dialog(self, waitTimeout=30) -> bool:
        '''
        Waits for the "Please set the couch, then review the contours. Click OK in this box to continue
        with calculating the reference plan on today's CBCT" message in the action required dialog to appear.

        Args:
            waitTimeout (int): The time in seconds to wait for the text in the dialog to appear

        Returns:
            bool - True if message is displayed in action required dialog, False otherwise
        '''
        try:
            return MonacoScriptingDialogsFuncs.check_for_set_couch_and_review_contours_dialog(waitTimeout)
        except Exception as e:
            logger.info(f"Message in Action Required dialog failed to appear or was not recognised. Error: {e}.")
            return False

    def wait_for_adapt_the_plan_dialog(self, waitTimeout=15) -> bool:
        '''
        Waits for the "Do you want to adapt the plan?" message in the action required dialog to appear.

        Args:
            waitTimeout (int): The time in seconds to wait for the text in the dialog to appear

        Returns:
            bool - True if message is displayed in action required dialog, False otherwise
        '''
        try:
            return MonacoScriptingDialogsFuncs.check_for_adapt_the_plan_dialog(waitTimeout)
        except Exception as e:
            logger.info(f"Message in Action Required dialog failed to appear or was not recognised. Error: {e}.")
            return False

    def wait_for_review_plan_and_approve_dialog(self, waitTimeout=60) -> bool:
        '''
        Waits for the "Review the plan and approve. Once approved, click OK to proceed with plan report creation"
        message in the action required dialog to appear.

        Args:
            waitTimeout (int): The time in seconds to wait for the text in the dialog to appear

        Returns:
            bool - True if message is displayed in action required dialog, False otherwise
        '''
        try:
            return MonacoScriptingDialogsFuncs.check_for_review_plan_and_approve_dialog(waitTimeout)
        except Exception as e:
            logger.info(f"Message in Action Required dialog failed to appear or was not recognised. Error: {e}.")
            return False

    def select_setup_adapt_ref_plan(self, refPlanMenuItem: str) -> None:
        '''
        Selects the Reference Plan combo box item from the setup adapt dialog based on the text provided.

        Args:
            refPlanMenuItem (str): Text string used to select the Reference Plan combo box item
        '''
        MonacoScriptingDialogsFuncs.click_setup_adapt_reference_plan_combobox()
        MonacoScriptingDialogsFuncs.select_ref_plan_combobox_item_by_text(comboItemText=refPlanMenuItem)

    def select_setup_adapt_daily_image(self, dailyImageMenuItem: str) -> None:
        '''
        Selects the Daily Image combo box item from the setup adapt dialog based on the text provided.

        Args:
            dailyImageMenuItem (str): Text string used to select the Daily Image combo box item
        '''
        MonacoScriptingDialogsFuncs.click_setup_adapt_daily_image_combobox()
        MonacoScriptingDialogsFuncs.select_daily_image_combobox_item_by_text(comboItemText=dailyImageMenuItem)

    def select_setup_adapt_ok_or_cancel_button(self, okButton: bool = True) -> None:
        '''
        Selects either the OK or Cancel button from the setup adapt dialog.

        Args:
            okButton (bool): True to select OK button, False to select Cancel button
        '''
        if okButton:
            MonacoScriptingDialogsFuncs.click_setup_adapt_ok_button()
        else:
            MonacoScriptingDialogsFuncs.click_setup_adapt_cancel_button()

    def select_action_required_ok_or_cancel_button(self, okButton: bool = True) -> None:
        '''
        Selects either the OK or Cancel button from the action required dialog.

        Args:
            okButton (bool): True to select OK button, False to select Cancel button
        '''
        if okButton:
            MonacoScriptingDialogsFuncs.click_action_required_ok_button()
        else:
            MonacoScriptingDialogsFuncs.click_action_required_cancel_button()

    def select_action_required_yes_or_no_button(self, yesButton: bool = True) -> None:
        '''
        Selects either the Yes or No button from the action required dialog.

        Args:
            yesButton (bool): True to select Yes button, False to select No button
        '''
        if yesButton:
            MonacoScriptingDialogsFuncs.click_action_required_yes_button()
        else:
            MonacoScriptingDialogsFuncs.click_action_required_no_button()